/* Synthetic interaction reference. No network, credentials, or persistent patient data. */
const titles={delivery:'Patient delivery',reminders:'Reminder rules',templates:'Message templates',inbox:'Staff notifications',preferences:'My notification preferences',rules:'Staff alert rules',providers:'Delivery setup',patient:'Patient experience',states:'Recovery states',handoff:'Implementation handoff'};
