 {id:'n1',kind:'assignment',title:'A document request was assigned to you',body:'Avery Brooks · Missing insurance card',meta:'Assigned by Alex Morgan · Downtown',at:'8:27 AM',unread:true,current:'Open',owner:'Maya Chen',due:'Today, 12:00 PM',location:'Downtown'},
 {id:'n2',kind:'overdue',title:'Your follow-up is overdue',body:'Maya Patel · Confirm paperwork completion',meta:'Due today at 8:00 AM · Downtown',at:'8:00 AM',unread:true,current:'Overdue',owner:'Maya Chen',due:'Today, 8:00 AM',location:'Downtown'},
 {id:'n3',kind:'ownership',title:'A work item you owned was reassigned',body:'Sofia Martinez · Review uploaded document',meta:'Maya Chen → Jordan Lee · Downtown',at:'Yesterday',unread:true,current:'Reassigned',owner:'Jordan Lee',due:'Today, 3:00 PM',location:'Downtown'},
 {id:'n4',kind:'delivery',title:'A patient message needs follow-up',body:'Noah Kim · Completed copy is available',meta:'Email failed · Alex Morgan is following up · Downtown',at:'8:15 AM',unread:false,current:'Open',owner:'Alex Morgan',due:'Today, 10:00 AM',location:'Downtown'},
 {id:'n5',kind:'assignment',title:'A document review was assigned to you',body:'Emma Wilson · Document review',meta:'Assigned by Alex Morgan · Northside',at:'Yesterday',unread:false,current:'Resolved',owner:'Maya Chen',due:'Completed yesterday',location:'Northside'}
