let state={page:'delivery',location:'All permitted locations',filter:'All',query:'',alertFilter:'All',event:'request',channel:'Email',locale:'en',patientState:'Message received',signedIn:false,demoState:'Default',rulesSaved:false,remindersSaved:false,reminderPolicies:{},autoReminders:false,composeChannel:'Email',smsActive:false,alerts:structuredClone(fixtureAlerts),deliveries:structuredClone(fixtureDeliveries)};
const savedForms={};
const app=document.getElementById('app'),modal=document.getElementById('modal');
let returnFocus=null,toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,classes='',extra='')=>`<button type="button" class="button ${classes}" data-action="${action}" ${extra}>${label}</button>`;
const tone=s=>['Delivered','Resolved','Verified','Completed'].includes(s)?'green':['Unknown','Scheduled','Overdue','Needs activation'].includes(s)?'amber':['Failed','Access removed'].includes(s)?'red':['Accepted','Queued','Open','Preview enabled'].includes(s)?'blue':'';
const badge=(s,t=tone(s))=>`<span class="badge ${t}">${esc(s)}</span>`;
const unread=()=>state.alerts.filter(x=>x.unread).length;
const scoped=list=>list.filter(x=>state.location==='All permitted locations'||x.location===state.location);
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function go(page){state.page=page;state.demoState='Default';state.query='';state.filter='All';render();document.getElementById('main').focus({preventScroll:true});window.scrollTo(0,0)}
function nav(page,icon){return `<button type="button" class="navbutton ${state.page===page?'active':''}" data-page="${page}" ${state.page===page?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span><span class="navtext">${titles[page]}</span>${page==='inbox'?`<span class="count">${unread()}</span>`:''}</button>`}
function saveForm(){savedForms[state.page+'|'+state.location]=[...document.querySelectorAll('main input,main select')].filter(x=>x.id!=='location').map(x=>({value:x.value,checked:x.checked}));}
function restoreForm(){const form=savedForms[state.page+'|'+state.location];if(form)[...document.querySelectorAll('main input,main select')].filter(x=>x.id!=='location').forEach((x,i)=>{if(form[i]){x.value=form[i].value;if(x.type==='checkbox'||x.type==='radio')x.checked=form[i].checked;}});}
function render(){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">+</span><span class="brandtext">Care<b>IQ</b></span></div><div class="practice"><strong>Evergreen Medical</strong><small>Practice workspace</small></div><nav aria-label="Design screens"><p class="navheading">Patient communication</p>${nav('delivery','↗')}${nav('reminders','◷')}${nav('templates','▤')}<p class="navheading section">Staff workspace</p>${nav('inbox','♧')}${nav('preferences','☷')}${nav('rules','⌘')}<p class="navheading section">Design review</p>${nav('providers','⚙')}${nav('patient','▯')}${nav('states','◇')}${nav('handoff','▱')}</nav><div class="sidebottom"><p>Synthetic records · Local simulation<br>No messages leave this prototype.</p><div class="profile"><span class="avatar">MC</span><div><strong>Maya Chen</strong>Practice manager · Demo</div></div></div></aside><div><header class="topbar"><div class="crumb">Evergreen Medical<span>›</span><strong>${titles[state.page]}</strong></div><div class="topactions"><span class="designbadge">DESIGN PROTOTYPE</span>${button(`Notifications ${unread()}`,'bell','small')}<span class="avatar">MC</span></div></header><div class="debugnote"><strong>Design review</strong><span>October 19, 2026 · 8:30 AM PT · Synthetic data</span><button type="button" data-action="reset">Reset demo</button></div><main id="main" tabindex="-1">${renderPage()}</main></div></div>`;wire();restoreForm();}
function intro(title,subtitle,action='',eyebrow='COMMUNICATIONS'){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`}
function scope(){return `<div class="scope"><label>Location<select id="location" aria-label="Working location">${['All permitted locations','Downtown','Northside'].map(x=>`<option ${x===state.location?'selected':''}>${x}</option>`).join('')}</select></label><span class="snapshot">Demo snapshot · 8:30 AM PT</span></div>`}
function renderPage(){if(state.demoState!=='Default'&&state.page==='delivery')return deliveryException();return ({delivery,reminders,templates,inbox,preferences,rules,providers,patient,states,handoff})[state.page]();}
function delivery(){const rows=scoped(state.deliveries),uncertain=rows.find(x=>x.status==='Unknown'),attention=rows.filter(x=>['Unknown','Failed'].includes(x.status)).length;return `${intro('Every message, accounted for.','Send requests, follow up on unfinished paperwork, and track each channel separately.',button('New patient message','compose','primary'))}${scope()}<div class="metrics">${[['All',rows.length,'Message intents in scope'],['Needs attention',attention,'Failed or unknown outcome'],['In progress',rows.filter(x=>['Queued','Accepted','Scheduled'].includes(x.status)).length,'Scheduled, queued or accepted'],['Delivered',rows.filter(x=>x.status==='Delivered').length,'Delivery receipt received']].map(([label,value,help])=>`<button type="button" class="metric ${label===state.filter?'active':''} ${label==='Needs attention'?'attention':''}" data-filter="${label}"><span>${label==='All'?'Messages today':label}</span><strong>${value}</strong><small>${help}</small></button>`).join('')}</div>${uncertain?`<div class="banner amber"><span class="symbol" aria-hidden="true">◷</span><div><strong>One ${uncertain.channel} message has an uncertain outcome</strong><p>Check the original send before starting another attempt.</p></div><div class="actions">${button('Review outcome','detail-'+uncertain.id,'small')}</div></div>`:''}<section class="panel" aria-label="Patient delivery log"><div class="toolbar"><div class="tabs" role="group" aria-label="Delivery status filter">${['All','Needs attention','In progress','Delivered','Suppressed'].map(x=>`<button type="button" class="tab ${state.filter===x?'active':''}" data-filter="${x}" aria-pressed="${state.filter===x}">${x}</button>`).join('')}</div><input class="search" id="search" aria-label="Search delivery log" placeholder="Search patient or message" value="${esc(state.query)}"></div><div id="deliveryrows">${deliveryRows()}</div></section><p class="footnote">Delivery receipts do not establish that a person read a message or completed paperwork. Each row is one message intent for one channel.</p>`}
function deliveryRows(){let rows=scoped(state.deliveries).filter(x=>{let match=state.filter==='All'||(state.filter==='Needs attention'?['Unknown','Failed'].includes(x.status):state.filter==='In progress'?['Queued','Accepted','Scheduled'].includes(x.status):x.status===state.filter);return match&&`${x.name} ${x.event} ${x.destination}`.toLowerCase().includes(state.query.toLowerCase())});if(!rows.length)return `<div class="empty"><span class="symbol">⌕</span><h2>No matching messages</h2><p>Adjust the current filter or patient search.</p>${button('Clear filters','clear-filters')}</div>`;return `<div class="tablewrap"><table class="deliverytable"><thead><tr><th>Patient</th><th>Message</th><th>Channel</th><th>Delivery</th><th>Latest update</th><th><span class="muted">Action</span></th></tr></thead><tbody>${rows.map(x=>`<tr><td><div class="person"><span class="avatar">${x.initials}</span><div><button class="textbutton" type="button" data-action="detail-${x.id}">${esc(x.name)}</button><span class="sub">${esc(x.location)}</span></div></div></td><td>${x.event}<span class="sub">${x.request}</span></td><td>${x.channel}<span class="sub">${x.destination}</span></td><td>${badge(x.status)}<span class="sub">${statusHelp(x.status)}</span></td><td>${x.at}</td><td>${button('View','detail-'+x.id,'small')}</td></tr>`).join('')}</tbody></table></div><div class="tablefoot"><span>${rows.length} messages · selected location scope</span><span>Times shown in Pacific Time</span></div>`}
function statusHelp(s){return ({Delivered:'Receipt from provider',Unknown:'Check before retry',Failed:'Staff follow-up needed',Suppressed:'Text messages opted out',Queued:'Waiting for dispatch',Accepted:'Provider accepted; receipt pending',Scheduled:'Waiting for allowed time'})[s]||'New message intent'}
function detail(id){const row=state.deliveries.find(x=>x.id===id);if(!row)return;const submitted=['Unknown','Failed','Delivered','Accepted'].includes(row.status),readonly=state.demoState==='Read only';const unknown=row.status==='Unknown',failed=row.status==='Failed',suppressed=row.status==='Suppressed';openDialog('Message delivery',`${row.name} · ${row.event}`,`<div class="banner ${unknown?'amber':failed?'red':row.status==='Delivered'?'green':''}"><span class="symbol">${failed?'!':unknown?'◷':'↗'}</span><div><strong>${row.status}</strong><p>${unknown?'The provider may have accepted the original SMS. Another send is blocked until this result is checked.':failed?'The receiving server rejected this address. The completed copy is still available in the patient library.':suppressed?'The recipient opted out of text messages. Staff cannot override this from the delivery log.':statusHelp(row.status)}</p></div></div><dl class="definition"><div><dt>${submitted?'Destination at dispatch':'Intended destination'}</dt><dd>${row.destination}</dd></div><div><dt>Channel and language</dt><dd>${row.channel} · English</dd></div><div><dt>Workflow state</dt><dd>${row.request}</dd></div><div><dt>Location</dt><dd>${row.location}</dd></div></dl><h3>Delivery activity</h3><ol class="timeline"><li><strong>Message intent created</strong><p>Policy, approved template and intended audience recorded.</p><small>Today, 8:14 AM · Maya Chen</small></li><li><strong>${submitted||suppressed?'Destination and current permission checked':'Dispatch eligibility pending'}</strong><p>${!submitted&&!suppressed?'Destination, access and policy will be rechecked immediately before the provider call.':suppressed?'SMS permission withdrawn; no provider call made.':'Verified destination revision and communication policy passed.'}</p><small>Today, 8:15 AM</small></li>${suppressed?'':!submitted?`<li><strong>${row.status==='Scheduled'?'Scheduled occurrence created':'Queued for dispatch'}</strong><p>No provider call has occurred.</p><small>${row.at} · No attempt started</small></li>`:`<li><strong>${unknown?'Send outcome unknown':failed?'Permanent rejection received':row.status==='Delivered'?'Delivery receipt received':row.status==='Accepted'?'Accepted by provider':'Waiting for dispatch'}</strong><p>${unknown?'The connection timed out after the dispatch boundary. Original attempt retained.':failed?'Email bounced. Automatic email to this destination is suppressed.':row.status==='Delivered'?'Provider receipt only; patient reading is not inferred.':statusHelp(row.status)}</p><small>${row.at} · Attempt 1</small></li>`}</ol>${failed?`<div class="reviewbox"><strong>Follow-up · Alex Morgan</strong><p>${row.event==='Completed paperwork'?'Confirm the destination and current authorized audience, then explicitly repair the notice’s access binding to the same exact library copy. Do not reopen or reissue the completed request.':'Confirm the destination through an approved process, then explicitly reissue the request to that corrected destination.'}</p></div>`:''}${unknown?'<p class="muted">If the provider cannot confirm the result, keep this message unknown and use an authorized assisted follow-up.</p>':''}`,`${button('Close','close')}${readonly?'':`${row.id==='d1'&&!unknown?button('Send reminder','manual-reminder-'+row.id):''}${unknown?button('Check original send','reconcile-'+id,'primary'):failed?button('Review destination & access','contact-'+id,'primary'):suppressed?button('Review communication choices','contact-'+id,'primary'):row.status==='Scheduled'?button('Cancel scheduled message','cancel-message-'+id,'danger'):button('Preview message','preview-message-'+id,'primary')}`}`)}
function openDialog(title,subtitle,body,footer){returnFocus=document.activeElement;modal.innerHTML=`<div class="dialoghead"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="close" type="button" data-action="close" aria-label="Close dialog">×</button></div><div class="dialogbody">${body}</div><div class="dialogfoot">${footer}</div>`;wire(modal);if(!modal.open)modal.showModal();}
function closeDialog(){modal.close();if(returnFocus?.isConnected)returnFocus.focus();}
modal.addEventListener('cancel',()=>setTimeout(()=>returnFocus?.isConnected&&returnFocus.focus(),0));
function compose(review=false){
 const channels=state.composeChannel==='Email + SMS'?['Email','SMS']:[state.composeChannel];
 const destinations=channels.map(c=>c==='Email'?'q•••@example.test':'••• ••• 0142').join(' and ');
 const content=review?`<div class="banner"><span class="symbol">↗</span><div><strong>Ready to queue ${channels.length===1?'one message':'two channel messages'}</strong><p>The server rechecks current request, recipient, destination and permission before each channel dispatch.</p></div></div><dl class="definition"><div><dt>Patient</dt><dd>Quinn Taylor</dd></div><div><dt>Request</dt><dd>Open · due Oct 22</dd></div><div><dt>Chosen channels</dt><dd>${state.composeChannel}</dd></div><div><dt>Recipient destinations</dt><dd>${destinations}</dd></div></dl>${channels.includes('Email')?emailPreview('request','en','q•••@example.test'):''}${channels.includes('SMS')?`<div class="section">${smsPreview('request','en')}</div>`:''}<p class="statehint">One intent per channel. An eligible partial success remains visible if the other channel fails. A replaced recipient or revoked link requires a reissue.</p>`:`<div class="banner"><span class="symbol">↗</span><div><strong>Use an existing request</strong><p>This message stays linked to the exact request and intended patient. Completed-copy notices are created separately.</p></div></div><label class="field"><span>Patient and request</span><select><option>Quinn Taylor · prepared request · due Oct 22</option></select></label><dl class="definition"><div><dt>Recipient</dt><dd>Patient · confirmed destinations</dd></div><div><dt>Location</dt><dd>Downtown</dd></div></dl><label class="field"><span>Delivery channel</span><select id="compose-channel">${['Email','SMS','Email + SMS'].map(x=>`<option ${x===state.composeChannel?'selected':''}>${x}</option>`).join('')}</select><small>Email: q•••@example.test · SMS: ••• ••• 0142. Both purposes are permitted for this synthetic patient.</small></label><label class="field"><span>Message language</span><select><option>English · approved version 1</option></select><small>Message language does not alter frozen paperwork language.</small></label><div class="reviewbox"><strong>Separate permission for each channel</strong><p>A stored address or phone number is insufficient. If neither channel is eligible, save the request and offer assisted completion.</p></div>`;
 openDialog(review?'Review patient message':'Send a paperwork request','Existing request · Quinn Taylor · Synthetic preview',content,button('Cancel','close')+button(review?'Queue demo messages':'Review message',review?'queue-message':'compose-review','primary'));
 const channel=document.getElementById('compose-channel');if(channel)channel.addEventListener('change',()=>state.composeChannel=channel.value);
}
function manualReminder(id){const row=state.deliveries.find(x=>x.id===id);openDialog('Review manual reminder',`${row.name} · existing request`, `<div class="banner amber"><span class="symbol">◷</span><div><strong>Reminder eligible after 9:22 AM PT</strong><p>The initial message was dispatched at 8:22 AM. The one-hour manual cooldown has not passed.</p></div></div><dl class="definition"><div><dt>Request state</dt><dd>Open · due Oct 22</dd></div><div><dt>Preferred channel</dt><dd>${row.channel}</dd></div><div><dt>Destination</dt><dd>${row.destination}</dd></div><div><dt>Recent dispatch</dt><dd>Today, 8:22 AM PT</dd></div></dl><p class="muted">An authorized manual reminder uses the same request, fresh restricted grant, limits and permission checks. It never creates another paperwork request.</p>`,button('Close','close')+button('Reminder available at 9:22 AM','close','primary','disabled'));}

function reminders(){return `${intro('A timely nudge, with clear limits.','Remind patients only while the request is open and communication remains permitted.',button(state.remindersSaved?'Rules saved':'Save reminder rules','save-reminders','primary',state.location==='All permitted locations'?'disabled':''))}${scope()}${state.location==='All permitted locations'?'<div class="banner"><strong>Select one location to edit reminder policy.</strong><p>All permitted locations is a read-only policy overview.</p></div>':''}<div class="two"><section class="panel"><div class="panelhead"><div><h2>Patient reminder schedule</h2><p>Proposed defaults · practice policy, scoped by location</p></div>${badge(state.location==='All permitted locations'?'Select location':state.reminderPolicies[state.location]?'Enabled in preview':'Off until enabled',state.reminderPolicies[state.location]?'green':'')}</div><div class="panelbody"><label class="check"><input type="checkbox" id="auto-reminders" ${state.reminderPolicies[state.location]?'checked':''}><span>Enable automatic patient reminders<small>Off by default until a location manager activates a reviewed policy.</small></span></label><div class="fieldrow"><label class="field"><span>First reminder before due time</span><select id="reminder-first"><option>48 hours before</option><option>72 hours before</option><option>24 hours before</option></select></label><label class="field"><span>Final reminder before due time</span><select id="reminder-final"><option>24 hours before</option><option>No final reminder</option></select></label></div><div class="fieldrow"><label class="field"><span>Earliest delivery time</span><input type="time" id="window-start" value="09:00"></label><label class="field"><span>Latest delivery time</span><input type="time" id="window-end" value="18:00"></label></div><label class="field"><span>Time zone policy</span><select><option>Recipient’s confirmed time zone</option></select><small>Missing recipient zone holds automatic reminders for review.</small></label><label class="check"><input type="checkbox" checked><span>Use the preferred permitted channel<small>No automatic switch to another channel after a failure.</small></span></label><label class="check"><input type="checkbox" checked><span>Create staff follow-up when the request becomes overdue<small>Patient reminders stop at the due time.</small></span></label><div class="reviewbox section"><strong>Applies to future unsent messages</strong><p>Recompute queued occurrences when rules or due times change. Preserve all previous delivery facts.</p></div><p class="inlineflag">Limit: 2 automatic reminders per request, at least 24 hours apart across channels; reissue does not reset this budget. Manual cooldown: 1 hour. Combined initial, reminder and resend cap: 3 messages per request/destination in 24 hours.</p></div></section><aside><div class="panel"><div class="panelhead"><h2>Example · due Thursday at noon</h2></div><div class="panelbody"><div class="scheduleline"><span class="number">1</span><div><strong>Tuesday · 12:00 PM</strong><p>48 hours before the due time</p></div></div><div class="scheduleline"><span class="number">2</span><div><strong>Wednesday · 12:00 PM</strong><p>24 hours before the due time</p></div></div><div class="scheduleline"><span class="number">✓</span><div><strong>Thursday · 12:00 PM</strong><p>Stop patient reminders; alert current owner if still open.</p></div></div></div></div><div class="banner section"><span class="symbol">✓</span><div><strong>Recheck before every send</strong><p>Completion, cancellation, expiry, opt-out, contact changes and authority changes can suppress an occurrence.</p></div></div></aside></div><p class="footnote">If shifting into an allowed delivery window would cross the due time, skip that occurrence. These are product defaults for review.</p>`}
const copy={en:{request:{subject:'A secure request from Evergreen Medical',title:'You have paperwork to complete',body:'Please open your secure request to complete your paperwork.',cta:'Open secure request',sms:'Evergreen Medical: Please complete your paperwork using your secure request.'},reminder:{subject:'A reminder from Evergreen Medical',title:'A reminder about your paperwork',body:'Your secure paperwork request is still open. Please complete it when you can.',cta:'Continue securely',sms:'Evergreen Medical: A reminder to complete your paperwork using your secure request.'},complete:{subject:'Your secure copy is ready',title:'Your paperwork is ready',body:'Sign in to view or download your completed copy.',cta:'View secure copy',sms:'Evergreen Medical: Your paperwork is ready. Sign in to view your secure copy.'}},es:{request:{subject:'Una solicitud segura de Evergreen Medical',title:'Tiene documentos por completar',body:'Abra su solicitud segura para completar los documentos.',cta:'Abrir solicitud segura',sms:'Evergreen Medical: Complete sus documentos mediante su solicitud segura.'},reminder:{subject:'Un recordatorio de Evergreen Medical',title:'Un recordatorio sobre sus documentos',body:'Su solicitud segura sigue abierta. Complete los documentos cuando pueda.',cta:'Continuar de forma segura',sms:'Evergreen Medical: Le recordamos que complete sus documentos mediante su solicitud segura.'},complete:{subject:'Su copia segura está lista',title:'Sus documentos están listos',body:'Inicie sesión para ver o descargar su copia completada.',cta:'Ver copia segura',sms:'Evergreen Medical: Sus documentos están listos. Inicie sesión para ver su copia segura.'}}};
function emailPreview(event=state.event,locale=state.locale,destination='a•••@example.test'){const c=copy[locale][event];return `<div class="email" lang="${locale}"><div class="emailhead"><strong>${c.subject}</strong>Evergreen Medical &lt;notifications@evergreen.example&gt;<br>To: ${destination}</div><div class="emailbody"><div class="brand"><span class="brandmark">+</span><span>Evergreen Medical</span></div><h3>${c.title}</h3><p>${c.body}</p>${button(c.cta,'patient-link','primary')}<small>${locale==='es'?'¿Necesita ayuda? Llame al consultorio al (555) 010-0100. No responda con información médica.':'Need help? Call the practice at (555) 010-0100. Do not reply with medical information.'}</small><small>${locale==='es'?'Puede cambiar sus preferencias de comunicación en su cuenta segura.':'You can change your communication preferences in your secure account.'}</small></div></div>`}
function smsPreview(event=state.event,locale=state.locale){const c=copy[locale][event];return `<div class="smsmeta">Evergreen Medical · Today, 8:22 AM</div><div class="sms" lang="${locale}">${c.sms}<span class="smslink">https://app.careiq.example/n/x6Zp</span>${locale==='es'?'Responda STOP para dejar de recibir mensajes. HELP para obtener ayuda. Pueden aplicarse tarifas de mensajes y datos.':'Reply STOP to opt out, HELP for help. Message and data rates may apply.'}</div><p class="smsmeta">Preview only · Segment count calculated by the final provider adapter</p>`}
function previewControls(){return `<div class="patientcontrols"><label class="field"><span>Channel</span><select id="channel"><option ${state.channel==='Email'?'selected':''}>Email</option><option ${state.channel==='SMS'?'selected':''}>SMS</option></select></label><label class="field"><span>Message language</span><select id="locale"><option value="en" ${state.locale==='en'?'selected':''}>English</option><option value="es" ${state.locale==='es'?'selected':''}>Español · proposed translation</option></select></label></div>`}
function templates(){return `${intro('Useful messages. Minimal detail.','Approved message templates keep paperwork and patient information inside the secure experience.',button('Preview patient journey','open-patient'))}<div class="two"><section><div class="templatecards" role="group" aria-label="Message event">${[['request','Paperwork request','Created after a request and eligible recipient are ready.'],['reminder','Paperwork reminder','Sent only for an open request and due occurrence.'],['complete','Completed paperwork','Sent after the exact copy is durably available.']].map(([id,title,description])=>`<button type="button" class="templatecard ${state.event===id?'active':''}" data-event="${id}" aria-pressed="${state.event===id}"><strong>${title}</strong><p>${description}</p><small>Version 1 · Approved fields only</small></button>`).join('')}</div><div class="banner section"><span class="symbol">⌁</span><div><strong>Secure links, no attachments</strong><p>No patient name, diagnosis, form title, answers, signatures, tracking pixel or third-party link shortener. The practice name still reveals a relationship and respects confidentiality choices.</p></div></div><p class="footnote">Spanish copy is a proposed translation and requires approval before activation. Template changes create a new version.</p></section><section>${previewControls()}<div class="messagepreview">${state.channel==='Email'?emailPreview():smsPreview()}</div><p class="footnote">Illustrative sender and link use reserved .example domains. Request links and completed-copy links use different authorization paths.</p></section></div>`}
function inbox(){const list=scoped(state.alerts).filter(x=>state.alertFilter==='Unread'?x.unread:state.alertFilter==='Overdue'?x.kind==='overdue':state.alertFilter==='Assignments'?['assignment','ownership'].includes(x.kind):true);return `${intro('The next thing that needs you.','Assignments, work ownership changes and overdue alerts, in one place.',button('Mark all as read','mark-all'))}${scope()}<section class="panel"><div class="toolbar"><div class="tabs" role="group" aria-label="Staff notification filter">${['All','Unread','Assignments','Overdue'].map(x=>`<button type="button" class="tab ${state.alertFilter===x?'active':''}" data-alert-filter="${x}" aria-pressed="${state.alertFilter===x}">${x}${x==='Unread'?` · ${scoped(state.alerts).filter(n=>n.unread).length}`:''}</button>`).join('')}</div>${button('My preferences','open-preferences','small')}</div>${list.length?list.map(x=>`<article class="inboxrow ${x.unread?'unread':''}"><div class="notificationicon ${x.kind==='overdue'?'amber':''}" aria-hidden="true">${x.kind==='overdue'?'◷':x.kind==='ownership'?'⇄':x.kind==='delivery'?'↗':'＋'}</div><div class="inboxtext"><button type="button" class="textbutton" data-action="alert-${x.id}">${x.unread?'<span class="unreaddot" aria-hidden="true"></span>':''}${x.title}${x.unread?'<span class="srtext"> · Unread</span>':''}</button><p>${x.body}</p><small>${x.meta}</small></div><div class="inboxaction"><time>${x.at}</time>${badge(x.current)}${button('Open','alert-'+x.id,'small')}</div></article>`).join(''):`<div class="empty"><span class="symbol">✓</span><h2>You’re caught up</h2><p>No ${state.alertFilter==='Unread'?'unread ':''}notifications in this location scope.</p></div>`}</section><p class="footnote">Reading a notification does not complete the work. The work item’s current status and owner remain authoritative.</p>`}
function alertDetail(id){const row=state.alerts.find(x=>x.id===id);row.unread=false;render();openDialog('Work item update',row.title,`<div class="banner ${row.current==='Overdue'?'amber':''}"><span class="symbol">${row.kind==='overdue'?'◷':'⇄'}</span><div><strong>Current state · ${row.current}</strong><p>${row.kind==='ownership'?'This work now belongs to Jordan Lee. Your earlier notification remains part of your history.':row.current==='Resolved'?'The work has already been completed. No follow-up action is needed.':'Open the source work item to review and take the next action.'}</p></div></div><h3>${row.body}</h3><dl class="definition"><div><dt>Current owner</dt><dd>${row.owner}</dd></div><div><dt>Due</dt><dd>${row.due}</dd></div><div><dt>Location</dt><dd>${row.location}</dd></div><div><dt>Your notification</dt><dd>Read · source work unchanged</dd></div></dl><h3>Event history</h3><ol class="timeline"><li><strong>${row.kind==='ownership'?'Ownership changed':row.kind==='overdue'?'Due time passed':row.kind==='delivery'?'Delivery failed':'Assignment changed'}</strong><p>${row.meta}</p><small>${row.at}</small></li><li><strong>Notification opened</strong><p>Marked as read only for Maya Chen.</p><small>Current demo time</small></li></ol>`,button('Close','close')+button('Open current work item','work-'+id,'primary'));}
function preferences(){return `${intro('Choose when you hear from us.','Personal delivery choices apply within Evergreen Medical. Your work queue remains available.',button('Save preferences','save-preferences','primary'))}<div class="two"><section class="panel"><div class="panelhead"><div><h2>My notification delivery</h2><p>Maya Chen · Evergreen Medical</p></div></div><div class="panelbody"><div class="settingrow"><div><strong>In-app notifications</strong><p>Assignments, work ownership and overdue alerts remain in your inbox.</p></div>${badge('Always available','blue')}</div>${[['New assignments','Immediate email'],['Ownership changes','Daily digest'],['Overdue work','Immediate email'],['Patient delivery failures','Daily digest']].map(([name,defaultValue],i)=>`<div class="settingrow"><div><strong>${name}</strong><p>${i===2?'Escalation is governed by the practice’s overdue rules.':'Choose an optional email outside the in-app inbox.'}</p></div><select aria-label="${name} email preference">${['Immediate email','Daily digest','In-app only'].map(x=>`<option ${x===defaultValue?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}<div class="fieldrow section"><label class="field"><span>Quiet hours begin</span><input type="time" value="18:00"></label><label class="field"><span>Quiet hours end</span><input type="time" value="08:00"></label></div><label class="field"><span>My time zone</span><select><option>America/Los_Angeles</option><option>America/New_York</option></select></label><label class="field"><span>Daily digest time</span><input type="time" value="08:30"><small>One practice-scoped summary with a secure link. No patient details in the email.</small></label></div></section><aside><div class="panel"><div class="panelhead"><h2>Email and lock-screen preview</h2></div><div class="panelbody"><div class="reviewbox"><strong>You have a new work update</strong><p>Sign in to CareIQ to review your work.</p></div><p>External previews omit patient names, document categories and record details. Fresh permission checks apply when you open the link.</p></div></div><div class="banner section"><span class="symbol">◷</span><div><strong>Quiet hours defer external alerts</strong><p>In-app work remains visible. If an item resolves before the deferred email is due, skip that email.</p></div></div><p class="footnote">Native push is a later adapter. The same generic preview and secure link apply; the first release needs in-app and optional staff email.</p></aside></div>`}
function rules(){return `${intro('Route the update to the right person.','Practice rules determine eligible recipients. A notification never grants access to a record.',button(state.rulesSaved?'Rules saved':'Save staff alert rules','save-rules','primary',state.location==='All permitted locations'?'disabled':''))}${scope()}${state.location==='All permitted locations'?'<div class="banner"><strong>Select one location to edit alert rules.</strong><p>Saving never applies silently to multiple locations.</p></div>':''}<section class="panel"><div class="panelhead"><div><h2>Event and recipient rules</h2><p>Work item ownership, separate from practice administration</p></div>${badge('Manager settings','blue')}</div><div class="tablewrap"><table class="rulematrix"><thead><tr><th>Trigger</th><th>Recipients</th><th>When</th><th>In app</th></tr></thead><tbody><tr><td><strong>Unassigned → assigned</strong><br><small>First work assignment</small></td><td>New eligible owner</td><td>After assignment commits</td><td><input class="switch" type="checkbox" checked aria-label="Enable first assignment alerts"></td></tr><tr><td><strong>Owner A → owner B</strong><br><small>One ownership change event</small></td><td>New owner; previous owner if still eligible<br><small>Exclude the acting user</small></td><td>After reassignment commits<br><small>No duplicate assignment alert</small></td><td><input class="switch" type="checkbox" checked aria-label="Enable ownership change alerts"></td></tr><tr><td><strong>Due time passes</strong><br><small>Open work only</small></td><td>Current eligible owner;<br>configured location queue if unassigned</td><td>Once per due-date revision</td><td><input class="switch" type="checkbox" checked aria-label="Enable overdue alerts"></td></tr><tr><td><strong>Still overdue after escalation</strong></td><td>Configured manager with record access</td><td>Once at the escalation threshold</td><td><input class="switch" type="checkbox" checked aria-label="Enable overdue escalation"></td></tr></tbody></table></div></section><div class="equal section"><section class="panel"><div class="panelhead"><h2>Overdue escalation</h2></div><div class="panelbody"><label class="field"><span>Escalate after</span><select><option>1 business day</option><option>4 business hours</option><option>2 business days</option></select><small>Business calendar: Monday–Friday, 9 AM–5 PM, practice time zone. Configured holidays excluded.</small></label><label class="field"><span>Location escalation recipient</span><select><option>Alex Morgan · authorized location manager</option><option>No eligible manager · configuration gap</option></select></label><p>If no recipient is eligible, retain the item in the unassigned queue and create a configuration issue. Never broaden record access.</p></div></section><aside class="panel"><div class="panelhead"><h2>Reduce duplicate alerts</h2></div><div class="panelbody"><label class="check"><input type="checkbox" checked><span>Skip notifications for my own changes</span></label><label class="check"><input type="checkbox" checked><span>Group updates for the same work item<small>Keep each event in the activity history.</small></span></label><label class="check"><input type="checkbox" checked><span>Cancel deferred alerts when work is resolved or rescheduled</span></label><p class="inlineflag">Assignment must be reconciled to unassigned when a member loses eligibility. An alert is never a substitute for that update.</p></div></aside></div>`}
function providers(){return `${intro('Connect delivery with clear evidence.','Sender readiness, callback health and controlled activation belong in one place.',button('Run demo checks','test-providers','primary'))}<div class="banner amber"><span class="symbol">◇</span><div><strong>Design preview · no live providers are connected</strong><p>Connection states below illustrate the activation flow. Synthetic test actions do not contact a provider.</p></div></div><div class="equal"><section class="panel"><div class="panelhead"><div><h2>Email</h2><p>Approved transactional adapter</p></div>${badge('Verified')}</div><div class="panelbody"><dl class="definition"><div><dt>Sender name</dt><dd>Evergreen Medical</dd></div><div><dt>Sender address</dt><dd>notifications@evergreen.example</dd></div><div><dt>Reply route</dt><dd>Practice support · configured</dd></div><div><dt>Tracking</dt><dd>Disabled</dd></div></dl>${[['Sender domain / SPF / DKIM','Verified'],['Domain alignment policy','Verified'],['Signed callback validation','Verified'],['Synthetic bounce test','Verified']].map(([a,b])=>`<div class="approval"><span>${a}</span>${badge(b)}</div>`).join('')}<div class="actions section">${button('Review email setup','email-setup')}${button('Queue test to staff','email-test','primary')}</div></div></section><section class="panel"><div class="panelhead"><div><h2>SMS</h2><p>Approved messaging-service adapter</p></div>${badge(state.smsActive?'Preview enabled':'Needs activation')}</div><div class="panelbody"><dl class="definition"><div><dt>Sender</dt><dd>••• ••• 0100</dd></div><div><dt>Message categories</dt><dd>Transactional paperwork only</dd></div><div><dt>STOP / HELP</dt><dd>Webhook route configured</dd></div><div><dt>Recipient permission</dt><dd>Required for each dispatch</dd></div></dl>${[['Sender registration and approval',state.smsActive?'Verified':'Needs activation'],['Signed status callback','Verified'],['Inbound opt-out / opt-in handling','Verified'],['Recipient time-zone policy','Verified']].map(([a,b])=>`<div class="approval"><span>${a}</span>${badge(b)}</div>`).join('')}<div class="actions section">${button('Review SMS setup','sms-setup')}${button(state.smsActive?'Pause SMS preview':'Activate SMS preview','activate-sms','primary')}</div></div></section></div><section class="panel section"><div class="panelhead"><h2>Operational safeguards</h2></div><div class="panelbody"><div class="settingrow"><div><strong>Global dispatch switch</strong><p>Pause new provider calls while preserving incoming delivery receipts and queued intent history.</p></div>${button('Preview paused state','pause-dispatch')}</div><div class="settingrow"><div><strong>Health and incidents</strong><p>Monitor oldest queued message, callback freshness, unknown outcomes, opt-out processing and retry limits.</p></div>${badge('Example healthy','green')}</div><div class="settingrow"><div><strong>Credentials</strong><p>Stored in the deployment secret manager. Staff settings show readiness and masked account references only.</p></div>${badge('No keys in this UI')}</div></div></section>`}
function patient(){return `${intro('A calm, secure patient journey.','Review the message, link recovery and completed-copy experience on a phone or desktop.','','PATIENT PREVIEW')}<div class="patientcontrols"><label class="field"><span>Journey</span><select id="patient-event">${[['request','Request'],['reminder','Reminder'],['complete','Completed copy']].map(([v,l])=>`<option value="${v}" ${state.event===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Patient state</span><select id="patient-state">${['Message received','Secure sign-in','Copy available','Expired link','Cancelled request','Preparing copy','Access unavailable','Communication choices','Open request'].map(x=>`<option ${state.patientState===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="patientstage">${state.patientState==='Message received'?`<div class="patientcontrols"><label class="field"><span>Message channel</span><select id="channel"><option ${state.channel==='Email'?'selected':''}>Email</option><option ${state.channel==='SMS'?'selected':''}>SMS</option></select></label></div><div class="messagepreview">${state.channel==='Email'?emailPreview():smsPreview()}${state.channel==='SMS'?button('Open secure link','patient-link','primary'):''}</div>`:patientSurface()}</div><p class="footnote">Prototype interactions simulate sign-in and protected access. Real identity, patient/proxy binding and the exact copy’s access grant are required in implementation.</p>`}
function patientSurface(){const ps=state.patientState;let content='';if(ps==='Open request')content=`<span class="badge blue">Access verified in demo</span><h2>Your request is ready</h2><p>Continue to review and complete your open paperwork request. Signing, if required, is a separate step.</p><div class="documentrow"><span class="number">▤</span><div><strong>Paperwork request</strong><small>Due October 22 · 12:00 PM PT</small></div>${badge('Open')}</div>${button('Continue to paperwork','open-paperwork','primary')}`;if(ps==='Communication choices')content=`<span class="badge blue">Communication choices</span><h2>How we contact you</h2><p>These choices affect paperwork messages. They do not change your signing consent or available secure copies.</p><label class="check"><input type="checkbox" checked><span>Paperwork requests by email<small>a•••@example.test · confirmed</small></span></label><label class="check"><input type="checkbox" checked><span>Paperwork reminders by email</span></label><label class="check"><input type="checkbox" checked><span>Completed-copy notices by email</span></label><div class="reviewbox"><strong>SMS is opted out</strong><p>Changing your phone number does not restore text permission. Use the approved opt-in verification process.</p></div>${button('Save demo choices','save-patient-choices','primary')}<small class="sub">Need another contact method? Call the practice.</small>`;if(ps==='Secure sign-in')content=`<span class="badge blue">Secure access</span><h2>${state.event==='complete'?'Your paperwork is ready':'Your secure request'}</h2><p>${state.event==='complete'?'Sign in to view your completed copy. A forwarded message does not give another person access.':'Continue to verify your access and complete your paperwork. This link does not show medical information on its own.'}</p>${button('Continue securely','patient-auth','primary')}<small class="sub">Use your approved patient account or request verification path.</small>`;if(ps==='Copy available')content=`<span class="badge green">Copy available</span><h2>Your paperwork is ready</h2><p>${state.signedIn?'You are viewing your secure library.':'Preview of the authenticated patient library.'}</p><div class="documentrow"><span class="number">▤</span><div><strong>Completed paperwork</strong><small>October 19, 2026 · Exact completed version</small></div>${badge('Ready','green')}</div>${button('View completed copy','view-copy','primary')}<small class="sub">Completed copy availability is independent of email or text delivery.</small>`;if(ps==='Expired link')content=`<span class="badge amber">Link expired</span><h2>Let’s get you a fresh link</h2><p>This request link is no longer active. Contact the practice to verify your access and request a replacement.</p>${button('Show practice contact','practice-help','primary')}<small class="sub">Opening this page does not create or send another link.</small>`;if(ps==='Cancelled request')content=`<span class="badge">Request closed</span><h2>This request is no longer available</h2><p>The practice closed this request. You do not need to complete it using this link.</p>${button('Show practice contact','practice-help')}`;if(ps==='Preparing copy')content=`<span class="badge blue">Preparing your copy</span><h2>Your submission was received</h2><p>We’re preparing the final copy. We’ll show it here when it’s ready. Please do not submit again.</p>${button('Check status','check-copy','primary')}<small class="sub">A completion notification is created only after the exact copy is available.</small>`;if(ps==='Access unavailable')content=`<span class="badge">Access unavailable</span><h2>We couldn’t open this link</h2><p>Contact the practice for help with your secure access.</p>${button('Show practice contact','practice-help','primary')}`;return `<div class="patienttop"><div class="brand"><span class="brandmark">+</span><span>Evergreen Medical</span></div><div class="patientcard">${content}</div><div class="patientfoot">Questions? (555) 010-0100<br>For emergencies, contact local emergency services.</div></div>`}
const statesData=[['Service unavailable','The log failed to load. Preserve the last confirmed view and give a retry.','red'],['Access removed','Clear protected content and require a permitted context.','red'],['No messages','A successful empty result differs from a load failure.','blue'],['Read only','Show delivery history; hide send, retry and configuration controls.','blue'],['Dispatch paused','Keep message intents and provider callbacks; stop new calls.','amber'],['Stale request','Retain the draft and reload current request/recipient revision.','amber'],['Unknown outcome','Reconcile the original provider call; prevent an uncontrolled resend.','amber'],['Opted out','Suppress the channel; offer authorized contact follow-up.',''],['No valid recipient','Save the request and create follow-up without claiming delivery.','amber']];
function states(){return `${intro('Failures need a next step.','Review the recovery paths that keep delivery and source-work status truthful.','','STATE COVERAGE')}<div class="stategrid">${statesData.map(([title,help,t])=>`<button type="button" class="statecard" data-state="${title}">${badge(title,t)}<strong>${title}</strong><p>${help}</p><span class="sub">Open this state →</span></button>`).join('')}</div><section class="panel section"><div class="panelhead"><h2>Additional states in the implementation handoff</h2></div><div class="panelbody bodycopy"><p>Loading and partial results; rate limit; retry exhausted; permanent bounce and complaint; changed contact; expired or cancelled request; missing translation; missing time zone; superseded copy; provider event arriving late; removed assignee; deep link to resolved, moved or inaccessible work; empty staff inbox.</p><p>All states need text labels, a currentness timestamp and an authorized recovery action. Disabled controls explain the reason.</p></div></section>`}
function deliveryException(){const s=state.demoState;let view='';if(s==='Service unavailable')view=`<div class="empty"><span class="symbol">!</span><h2>We couldn’t load the delivery log</h2><p>Message outcomes have not changed. Try loading again.</p>${button('Try again','recover','primary')}</div>`;else if(s==='Access removed')view=`<div class="empty"><span class="symbol">◇</span><h2>This location is no longer available</h2><p>Protected records have been cleared. Select a location you can access.</p>${button('Choose permitted location','recover','primary')}</div>`;else if(s==='No messages')view=`<div class="empty"><span class="symbol">↗</span><h2>No patient messages yet</h2><p>Send a notification for an eligible open paperwork request.</p>${button('New patient message','compose','primary')}</div>`;else if(s==='Read only')view=`<div class="banner"><strong>Read-only access</strong><p>You can view permitted history. Sending and changing settings require additional permission.</p></div><div class="panel">${deliveryRows()}</div>`;else if(s==='Dispatch paused')view=`<div class="banner amber"><span class="symbol">Ⅱ</span><div><strong>Patient delivery is paused</strong><p>Queued messages remain pending. Delivery callbacks continue to update past attempts.</p></div></div><div class="panel">${deliveryRows()}</div>`;else if(s==='Stale request')view=`<div class="banner amber"><span class="symbol">⇄</span><div><strong>This request changed</strong><p>The recipient or request revision is newer than your draft. Review current details before sending.</p></div></div><div class="reviewbox"><strong>Your draft is retained</strong><p>Paperwork request · Email · English · Avery Brooks</p></div>${button('Review current request','compose','primary')}`;else if(s==='Unknown outcome')view=`<div class="banner amber"><span class="symbol">◷</span><div><strong>The original send needs reconciliation</strong><p>Another attempt is blocked while acceptance remains uncertain.</p></div></div>${button('Review original send','detail-d2','primary')}`;else if(s==='Opted out')view=`<div class="banner"><span class="symbol">⊘</span><div><strong>SMS is opted out</strong><p>No further automatic texts will be sent. Changing this contact field does not restore permission.</p></div></div>${button('Review communication choices','contact-d4','primary')}`;else view=`<div class="banner amber"><span class="symbol">!</span><div><strong>No eligible delivery destination</strong><p>The request is saved. Collect and verify an authorized destination or offer assisted completion.</p></div></div>${button('Create contact follow-up','contact-followup','primary')}`;return `${intro(s,'Patient delivery · recovery preview',button('Back to all states','open-states'))}${view}<p class="footnote">This is a synthetic state preview. Production permissions and request revisions are enforced by the server.</p>`}
function handoff(){return `${intro('From intent to a reliable outcome.','UI, delivery policy and backend boundaries for patient messages and internal work alerts.','','IMPLEMENTATION HANDOFF')}<section class="panel"><div class="panelhead"><h2>Shared delivery pipeline</h2></div><div class="panelbody"><div class="flow">${[['1 · Commit the event','Request, completion or assignment and its outbox event commit together.'],['2 · Resolve eligibility','Choose the current permitted audience, destination and template.'],['3 · Dispatch once per attempt','Lease the job, record the boundary and call an approved adapter.'],['4 · Reconcile evidence','Verify callbacks, preserve facts and surface unknown outcomes.']].map(([a,b])=>`<div class="flowstep"><strong>${a}</strong><small>${b}</small></div>`).join('')}</div><div class="equal bodycopy"><div><h3>Patient messaging</h3><p>Extend existing delivery records. Initial requests, reminders and completed-copy notices share attempt mechanics but retain separate business uniqueness and access grants.</p><p>Accepted, delivered, read, signed and staff-reviewed remain separate facts. Completed-copy availability does not depend on provider success.</p></div><div><h3>Staff alerts</h3><p>Add recipient-specific inbox records. Assignment and ownership changes emit one committed source event. Due-date revisions and escalation thresholds prevent repeated overdue alerts.</p><p>Read and unread are personal states. Current source-work status is fetched under current location and record permissions.</p></div></div></div></section><div class="equal section"><section class="panel"><div class="panelhead"><h2>Implementation sequence</h2></div><div class="panelbody"><ol class="ruleslist"><li>Extend schema, delivery attempts, restricted-link handoff and transactional outbox.</li><li>Add adapter contract, worker leases, suppression, reconciliation and signed callbacks.</li><li>Connect the delivery log, request composer, reminder policy and completed-copy status.</li><li>Add staff inbox, event recipients, overdue scheduling and preferences.</li><li>Verify integration, privacy, tenant boundaries and recovery before controlled activation.</li></ol></div></section><section class="panel"><div class="panelhead"><h2>Review package</h2></div><div class="panelbody bodycopy"><p>The accompanying design handoff includes screen requirements, reusable components, message copy, API and schema changes, event rules, acceptance cases and source integration points.</p><div class="actions section"><a class="button" href="../design-handoff.md">Design handoff</a><a class="button" href="../backend-design.md">Backend design</a><a class="button" href="../acceptance-checklist.md">Acceptance checklist</a></div><p class="footnote">These are proposed implementation designs. Prototype checks validate local interactions and layout; no provider is activated or live message delivered.</p></div></section></div>`}
function contact(id){const row=state.deliveries.find(x=>x.id===id);const completed=row.event==='Completed paperwork';openDialog('Review communication choices',`${row.name} · current destination and permission`,`${row.status==='Suppressed'?`<div class="banner"><strong>Text messages are opted out</strong><p>Only a verified opt-in workflow can restore eligibility. Staff cannot override the suppression.</p></div>`:`<div class="banner amber"><strong>Confirm a corrected destination</strong><p>${completed?'Confirm the corrected destination and explicitly repair the completed-copy audience grant. The notice stays bound to the same immutable library copy; do not reopen or reissue the completed paperwork request.':'Update the contact record through the approved verification process. A reissue creates a fresh restricted grant and revokes the replaced request link.'}</p></div>`}<label class="field"><span>Follow-up note</span><textarea id="contact-note" placeholder="Describe the approved contact follow-up. Do not enter medical details."></textarea></label><label class="field"><span>Follow-up owner</span><select><option>Alex Morgan · eligible Downtown staff</option><option>Maya Chen · eligible Downtown staff</option></select></label><div id="contact-error" class="error" role="alert"></div>`,button('Cancel','close')+button('Create demo follow-up','save-contact','primary'));}
function work(id){const row=state.alerts.find(x=>x.id===id);openDialog('Current work item',row.body,`<div class="banner ${row.current==='Overdue'?'amber':''}"><strong>${row.current}</strong><p>Current record fetched with fresh practice and location access.</p></div><dl class="definition"><div><dt>Owner</dt><dd>${row.owner}</dd></div><div><dt>Location</dt><dd>${row.location}</dd></div><div><dt>Due</dt><dd>${row.due}</dd></div><div><dt>Notification</dt><dd>Read · independent of work status</dd></div></dl><p class="muted">The production link opens the existing workflow work item. This design preserves its assignment and due-date commands.</p>`,button('Close','close')+(row.current!=='Resolved'?button('Complete demo follow-up','resolve-'+id,'primary'):''));}
function runAction(action){if(action.startsWith('manual-reminder-'))return manualReminder(action.slice(16));if(action.startsWith('detail-'))return detail(action.slice(7));if(action.startsWith('alert-'))return alertDetail(action.slice(6));if(action.startsWith('work-'))return work(action.slice(5));if(action.startsWith('contact-')&&action!=='contact-followup')return contact(action.slice(8));if(action.startsWith('resolve-')){const row=state.alerts.find(x=>x.id===action.slice(8));row.current='Resolved';row.due='Completed just now';closeDialog();render();return toast('Work item completed in the demo. Notification stays read.');}if(action.startsWith('reconcile-')){const row=state.deliveries.find(x=>x.id===action.slice(10));row.status='Delivered';row.at='8:30 AM';closeDialog();render();detail(row.id);return toast('Simulated provider query found the original delivery receipt. No second send.');}if(action.startsWith('cancel-message-')){const row=state.deliveries.find(x=>x.id===action.slice(15));row.status='Cancelled';closeDialog();render();return toast('Scheduled message cancelled in the demo. Request remains open.');}if(action.startsWith('preview-message-')){const row=state.deliveries.find(x=>x.id===action.slice(16));state.event=row.event==='Completed paperwork'?'complete':row.event==='Reminder'?'reminder':'request';state.channel=row.channel;closeDialog();return go('templates');}
switch(action){case 'bell':return go('inbox');case 'open-patient':return go('patient');case 'open-preferences':return go('preferences');case 'open-states':return go('states');case 'close':return closeDialog();case 'compose':return compose();case 'compose-review':return compose(true);case 'queue-message':(state.composeChannel==='Email + SMS'?['Email','SMS']:[state.composeChannel]).filter(channel=>!state.deliveries.some(x=>x.name==='Quinn Taylor'&&x.channel===channel&&x.event==='Paperwork request')).forEach(channel=>state.deliveries.unshift({id:'d'+(state.deliveries.length+1),name:'Quinn Taylor',initials:'QT',event:'Paperwork request',channel,destination:channel==='Email'?'q•••@example.test':'••• ••• 0142',status:'Queued',at:'8:30 AM',request:'Open · due Oct 22',location:'Downtown'}));closeDialog();render();return toast('Demo messages queued. Provider acceptance and delivery are still pending.');case 'clear-filters':state.filter='All';state.query='';return render();case 'mark-all':scoped(state.alerts).forEach(n=>n.unread=false);render();return toast('Notifications in this location scope marked as read. Work status unchanged.');case 'save-patient-choices':saveForm();return toast('Communication choices saved in this preview. SMS remains opted out.');case 'save-preferences':saveForm();return toast('Personal preferences saved for this demo view.');case 'save-reminders':{if(state.location==='All permitted locations')return;const start=document.getElementById('window-start').value,end=document.getElementById('window-end').value;if(!start||!end||start>=end)return toast('Choose an end time after the start time.');saveForm();state.remindersSaved=true;state.autoReminders=document.getElementById('auto-reminders').checked;state.reminderPolicies[state.location]=state.autoReminders;return toast('Reminder policy saved in this demo. Future unsent occurrences will be recomputed.');}case 'save-rules':if(state.location==='All permitted locations')return;saveForm();state.rulesSaved=true;return toast('Staff alert rules saved in this demo view.');case 'patient-link':if(modal.open)closeDialog();state.page='patient';state.patientState='Secure sign-in';render();window.scrollTo(0,0);return;case 'patient-auth':state.signedIn=true;state.patientState=state.event==='complete'?'Copy available':'Open request';render();return toast('Synthetic verification completed. No real authentication occurred.');case 'open-paperwork':return openDialog('Continue to existing paperwork flow','Verified request · same scoped patient session','<p>The implementation opens the existing patient form or signing workflow. Verification alone never submits a form, records a signature or creates a completed copy.</p>',button('Close','close'));case 'check-copy':state.patientState='Copy available';return render();case 'view-copy':return openDialog('Completed copy','Authenticated patient library · exact-version preview','<div class="banner green"><strong>Exact completed version available</strong><p>The real implementation streams the immutable authorized copy after a fresh access check.</p></div><p class="muted">This prototype contains no patient file or downloadable medical content.</p>',button('Close','close'));case 'practice-help':return openDialog('Contact Evergreen Medical','Synthetic practice support','<p>Call <strong>(555) 010-0100</strong> for help accessing your paperwork.</p><p class="statehint">Contacting the practice does not send another notification automatically.</p>',button('Close','close'));case 'save-contact':{const note=document.getElementById('contact-note');if(!note.value.trim()){document.getElementById('contact-error').textContent='Add a short follow-up note.';note.focus();return;}closeDialog();return toast('Demo contact follow-up created. No message was sent and no opt-out was changed.');}case 'contact-followup':return toast('Demo contact follow-up added to the eligible location queue.');case 'recover':state.demoState='Default';return render();case 'pause-dispatch':state.page='delivery';state.demoState='Dispatch paused';return render();case 'activate-sms':state.smsActive=!state.smsActive;render();return toast(state.smsActive?'SMS activation simulated. No live service connected.':'SMS paused in the preview.');case 'test-providers':return openDialog('Synthetic provider checks','No external requests made','<div class="banner green"><strong>Preview checks passed</strong><p>Email acceptance, delivery, bounce, SMS delivery and opt-out event paths are represented in the design.</p></div><p class="muted">Real activation requires an approved provider, sender, secret management, signed-callback tests and environment verification.</p>',button('Close','close'));case 'email-test':return openDialog('Queue a staff test email','Controlled activation design','<label class="field"><span>Allowlisted staff destination</span><select><option>m•••@evergreen.example · verified staff</option></select><small>Synthetic non-patient payload only. Unknown outcomes must be reconciled before retry.</small></label>',button('Cancel','close')+button('Simulate test queue','queue-test','primary'));case 'queue-test':closeDialog();return toast('Staff test simulated. No email sent.');case 'sms-setup':case 'email-setup':return openDialog(action==='sms-setup'?'SMS activation checklist':'Email activation checklist','Manager view · deployment credentials remain outside this UI',`<ol class="ruleslist"><li>Approve vendor, contract, sender identity and environment.</li><li>Configure sender and callback signing through the secret manager.</li><li>Verify accepted, delivered, failed and unknown-result recovery.</li><li>Test suppression, consent withdrawal and current access.</li><li>Activate a limited allowlist, then expand after review.</li></ol>`,button('Close','close'));case 'reset':Object.keys(savedForms).forEach(x=>delete savedForms[x]);state={...state,page:'delivery',location:'All permitted locations',filter:'All',query:'',alertFilter:'All',event:'request',channel:'Email',locale:'en',patientState:'Message received',signedIn:false,demoState:'Default',reminderPolicies:{},autoReminders:false,smsActive:false,alerts:structuredClone(fixtureAlerts),deliveries:structuredClone(fixtureDeliveries)};render();return toast('Synthetic design reset.');}}
function wire(root=app){root.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.page)));root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>runAction(el.dataset.action)));root.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>{state.filter=el.dataset.filter;render()}));root.querySelectorAll('[data-alert-filter]').forEach(el=>el.addEventListener('click',()=>{state.alertFilter=el.dataset.alertFilter;render()}));root.querySelectorAll('[data-event]').forEach(el=>el.addEventListener('click',()=>{state.event=el.dataset.event;render()}));root.querySelectorAll('[data-state]').forEach(el=>el.addEventListener('click',()=>{state.page='delivery';state.demoState=el.dataset.state;render()}));const location=root.querySelector('#location');if(location)location.addEventListener('change',()=>{state.location=location.value;render()});const search=root.querySelector('#search');if(search)search.addEventListener('input',()=>{state.query=search.value;document.getElementById('deliveryrows').innerHTML=deliveryRows();wire(document.getElementById('deliveryrows'))});for(const[id,key]of[['channel','channel'],['locale','locale'],['patient-event','event'],['patient-state','patientState']]){const el=root.querySelector('#'+id);if(el)el.addEventListener('change',()=>{state[key]=el.value;render()});}}
window.careiqDesign={snapshot:()=>structuredClone(state),configure:values=>{Object.assign(state,values);render()},reset:()=>runAction('reset')};
render();
